"""Frost Code lessons: basic Python and C, written by Claude. A lesson = a task said in several ways -> a short explanation and the code.
Python snippets are run by code_check.py to make sure they work; C snippets could not be compiled (no C compiler on this PC)."""

PY, C = "Python", "C"
TASKS = []            # (language, [ways to say the task], explanation, code, expected output or None)


def T(lang, phrases, why, code, out=None):
    TASKS.append((lang, phrases if isinstance(phrases, list) else [phrases], why, code.strip("\n"), out))


