def lesson_rows():
    """-> (category, wordings, reply) for the lesson store"""
    rows = []
    for lang, phrases, why, code, out in TASKS:
        fence = "python" if lang == PY else "c"; reply = f"{why}\n\n```{fence}\n{code}\n```"
        w = []
        for ph in phrases:
            for tpl in ("write a {l} program to {p}", "{p} in {l}", "{l} {p}", "how do i {p} in {l}", "show me {l} code to {p}", "{l} code to {p}", "code for {p} in {l}", "how to {p} in {l}", "{p} {l} example", "give me a {l} example to {p}", "can you {p} in {l}"):
                w.append(tpl.format(l=lang.lower(), p=ph))
            if lang == PY:
                w += [ph, "how do i " + ph, "write code to " + ph, "code to " + ph, "show me how to " + ph]
        rows.append((f"{lang} {phrases[0]}", w, reply))
    return rows


